using System.Numerics;
using WL;
using WLO;
using WoowzTile;
using WoowzTile.Objects;
using Char = WoowzTile.Objects.Char;
#pragma warning disable CS8618

namespace GOLUWorld;

public enum T_Block : byte{
    Empty = 0,
    Metal = 1,
    Ground_Planks = 2,
    Ground_Asphalt = 3,
    Bricks = 4,
    Ground_Sand = 5,
    Water = 6,
    Black = 7,
    Ground_Grass = 8,
    Error = 9
}

public enum T_Entity : byte{
    Empty = 0,
    Chair = 1,
    Table = 2,
    Spikes = 3,
    Mob_Spider = 4,
    Tree = 5,
    Item = 6,
    Crate = 7,
    Grass = 8,
    Bush = 9,
    Error = 10
}

public enum T_Item : byte{
    Empty = 0,
    FirstAidKit = 1,
    GPS = 2
}

public enum T_Interface : byte{
    None = 0,
    Inventory = 1,
    Menu = 2
}

public enum T_Decal : byte{
    Track = 0,
    Blood = 1,
    Zero  = 2,
    One   = 3
}

public enum T_Emotion : byte{
    Happiness = 0
}

public enum T_Thoughts : byte{
    Idle   = 0,
    Damage = 1,
    Heal   = 2
}

public enum T_Level : byte{
    None = 0,
    
    /* Спокойный уровень, чёрно-белый, больше белого, земляной покров, стены из металла и кирпичей */
    Calm = 1,
    /* Тёмно-серый, красный уровень, металлические стены, трубы, завод */
    Industrial = 2,
    /* Лабиринт, из стекла и зеркал */
    Labyrinth = 3,
    /* Пустыня залитая машинным маслом */
    OilDesert = 4,
    /* Электрический уровень, микросхемы, всё бьёт током */
    Electric = 5,
    /* Всё расплавленное, горячее */
    DangerHot = 6,
    /* Мир состоящий из глитчей */
    Glitch = 7,
    /* Закулисье))) */
    BackRooms = 8,
    /* Храм GOLU */
    GOLUTemple = 9,
    /* Мир WoowzCore */
    WoowzCore = 10
}

public struct Block{
    public Block(){}
    
    public int     X = 0;
    public int     Y = 0;
    public T_Block ID = T_Block.Empty;
}
    
public struct Entity{
    public Entity(){}

    public int             X          = 0;
    public int             Y          = 0;
    public T_Entity        ID         = T_Entity.Empty;
    public byte            Info       = 0;
    public Vector2I        InfoVector = Vector2I.Zero;
    public TextureRotation Rotation = TextureRotation.None;
}

