    /*
     * Блоки:
     * '_' - Пустота
     * '#' - Блок металла (блок)
     * ''' - Доски (пол)
     * 'A' - Асфальт (пол)
     * 'B' - Кирпичи (блок)
     * 'S' - Песок (пол)
     * 'W' - Вода (блок)
     * 'b' - Чёрный блок (блок)
     * '^' - Трава (пол)
     * 'Д' - [ГЕНЕРАТОР] Случайно, трава или пустота
     * 
     * Сущности:
     * '_' - Пустота
     * 'C' - Стул
     * 'T' - Стол
     * '^' - Шипы
     * 's' - Паук (моб)
     * '!' - Дерево
     * '#' - Ящик (толкаемый блок)
     * '~' - Трава
     * '3' - Куст
     * 'Д' - [ГЕНЕРАТОР] Случайно, дерево или трава или куст или пустота
     * 'д' - [ГЕНЕРАТОР] Случайно, трава или куст или пустота
     *
     * Коллизии:
     * L1 - Мир и игрок
     * L2 - Наносит урон если ходить в нём
     * L3 - Наносит всегда урон
     * L4 - Предмет
     * L5 - Толкаемый блок
     */
    
    public override string Name(){ return "GOLUWorld"; }

    public override string WindowTitle(){ return Emotion_Happiness + " | " + InsideCollision + " (" + CollisionInfo1 + ", " + CollisionInfo2 + ", " + CollisionInfo3 + ") | " + Seed + " | " + IgnoreColliders + " | " + Time + " (" + DayPhase + ")"; }

