byte[] Concat(params byte[][] buffers){
    int total = 0;
    foreach(var b in buffers) total += b.Length;
    byte[] result = new byte[total];
    int offset = 0;
    foreach(var b in buffers){
        System.Buffer.BlockCopy(b, 0, result, offset, b.Length);
        offset += b.Length;
    }
    return result;
}

