                float t = (float)i / samples;
                float pitch = startPitch + t * (endPitch - startPitch);
                float phase = 2 * (float)System.Math.PI * pitch * i / sampleRate;

                float sine = (float)System.Math.Sin(phase);
                float noise = ((float)rand.NextDouble() * 2 - 1) * 0.3f;
                float envelope = 1.0f - t;

                buffer[i] = (byte)(128 + (sine + noise) * 50 * envelope);
            }

            return buffer;
        }
        
        WL.System.Sound.Play(Generate());*/
