    private void Heal(uint Heal, bool FirstAidKit = false){
        if(Heal == 0){ return; }
        
        Health += Heal;
        if(Health > HealthMax){ Health = HealthMax; }

        if(FirstAidKit){ LastHealed = 60; SayThoughts(T_Thoughts.Heal); }
        
        EmotionChange(T_Emotion.Happiness, (int)(Heal / 2));
    }
    
    public override void Update(TickData TD){
        ClearColliders();

        if(InMainMenu){
            return;
        }

        StopTime = Interface != 0;

        if(StopTime){ return; }

        OutsideLevel = PlayerX - WorldX < -LevelSizeTile.X || PlayerX - WorldX > LevelSizeTile.X || PlayerY - WorldY < -LevelSizeTile.Y || PlayerY - WorldY > LevelSizeTile.Y;

        Time += (float)TD.DeltaTimeS * TimeSpeed;
        if(Time > MaxTime){ Time = 0; }
        
        if(Immortality){ if(Health < 1){ Health = 1; } }
        
        if(!Dead){
            if(OutsideLevel){
                Damage(WL.Math.Random.Fast_Bool(0.05f) ? (uint)WL.Math.Random.Fast_Int(1, 10) : 0);
            }else{
                Heal((uint)(WL.Math.Random.Fast_Bool(0.001f) ? 1 : 0));   
            }
            
            EmotionChange(T_Emotion.Happiness, WL.Math.Random.Fast_Bool(0.01f) ? 1 : 0);
            
            if(WL.Math.Random.Fast_Bool(0.001f)){ SayThoughts(T_Thoughts.Idle); }
        }else{
            Interface = 0;
        }

        if(ThoughtsTimer < 0 || Dead){ Thoughts = ""; ThoughtsContext = T_Thoughts.Idle; }else{ ThoughtsTimer -= (float)TD.DeltaTimeS; }
        
        foreach(Block Block in __Blocks.Values){
            if(Block.ID is T_Block.Metal or T_Block.Bricks or T_Block.Water or T_Block.Black or T_Block.Error){
                AddCollider(new Collider(WorldX + Block.X, WorldY + Block.Y, 16, 16));
            }
        }

        foreach(KeyValuePair<EntityKey, Entity> KVP in __Entities){
            Entity Entity = KVP.Value;
            
            if(Entity.ID is T_Entity.Table or T_Entity.Spikes or T_Entity.Mob_Spider or T_Entity.Tree){
                if(Entity.ID == T_Entity.Mob_Spider){
                    int SpiderSpeed = WL.Math.Random.Fast_Bool(0.8f) ? 1 : 0;
                    
                    byte Info = Entity.Info;
                    if(WL.Math.Random.Fast_Bool(Info == 1 ? 0.5f : 0.05f)){
                        if(WL.Math.Random.Fast_Bool(0.05f)){
                            Info = 2;
                        }else{
                            Info = (byte)(Info == 1 ? 0 : 1);
                        }
                    }

                    int PlayerX__ = PlayerX - WorldX;
                    int PlayerY__ = PlayerY - WorldY;

                    float Distance = Vector2I.Distance(new Vector2I(Entity.X, Entity.Y), new Vector2I(PlayerX__, PlayerY__));

                    Vector2I MoveDirection = Vector2I.Zero;
                    
                    Vector2I Target = Entity.InfoVector;
                    Vector2I EntityPositionOriginal = new Vector2I(Entity.X, Entity.Y);
                    
                    if(Distance < 100 && Rotten < 10){

                        Target.X = Info is 1 or 2 ? WorldX - PlayerX : PlayerX__;
                        Target.Y = Info is 1 or 2 ? WorldY - PlayerY : PlayerY__;

                        MoveDirection.X = WL.Math.Sign(Target.X - Entity.X) * SpiderSpeed;
                        MoveDirection.Y = WL.Math.Sign(Target.Y - Entity.Y) * SpiderSpeed;
                        
                        Entity.X += MoveDirection.X;
                        Entity.Y += MoveDirection.Y;
                        Entity.Info = Info;
                        
                    }else{
                        if(WL.Math.Random.Fast_Bool(0.05f) || Target == Vector2I.Zero){
                            Target = new Vector2I(WL.Math.Random.Fast_Int(-1000, 1000), WL.Math.Random.Fast_Int(-1000, 1000));
                        }
                        
                        MoveDirection.X = WL.Math.Sign(Target.X - Entity.X) * SpiderSpeed;
                        MoveDirection.Y = WL.Math.Sign(Target.Y - Entity.Y) * SpiderSpeed;

                        Entity.X += MoveDirection.X;
                        Entity.Y += MoveDirection.Y;
                        Entity.Info = Info;
                        Entity.InfoVector = Target;
                    }

                    if(MoveDirection != Vector2I.Zero){
                        int DirectionX = 0;
                        int DirectionY = 0;

                        float DX = Target.X - EntityPositionOriginal.X;
                        float DY = Target.Y - EntityPositionOriginal.Y;

                        int __AbsX = (int)WL.Math.Abs(DX);
                        int __AbsY = (int)WL.Math.Abs(DY);
                        if(__AbsX > __AbsY){
                            DirectionX = WL.Math.Sign(DX);
                        }else if(__AbsX < __AbsY){
                            DirectionY = WL.Math.Sign(DY);
                        }
                        
                        Entity.Rotation = DirectionX == 1 ? TextureRotation.Rotate270 : (DirectionX == -1 ? TextureRotation.Rotate90 : (DirectionY == -1 ? TextureRotation.Rotate180 : TextureRotation.None));
                    }
                    __Entities[KVP.Key] = Entity;
                }
                
                uint SizeX = 16;
                uint SizeY = 16;
                if(Entity.ID is T_Entity.Table or T_Entity.Tree){
                    SizeX = SizeY = 4;
                }

                CollisionLayer Layer = CollisionLayer.L1;
                if(Entity.ID == T_Entity.Spikes){
                    Layer = CollisionLayer.L2;
                }else if(Entity.ID == T_Entity.Mob_Spider){
                    Layer = CollisionLayer.L3;
                }
                AddCollider(new Collider(WorldX + Entity.X + (int)((16 - SizeX)/2), WorldY + Entity.Y + (int)((16 - SizeY)/2), SizeX, SizeY, 0, KVP.Key.Position, (int)KVP.Key.UniqueID, Layer));
            }

            if(Entity.ID is T_Entity.Item){
                AddCollider(new Collider(WorldX + Entity.X, WorldY + Entity.Y, 16, 16, Entity.Info, KVP.Key.Position, (int)KVP.Key.UniqueID, CollisionLayer.L4));
            }
            
            if(Entity.ID is T_Entity.Crate){
                AddCollider(new Collider(WorldX + Entity.X + 2, WorldY + Entity.Y + 2, 12, 12, 0, KVP.Key.Position, (int)KVP.Key.UniqueID, CollisionLayer.L5));
            }
        }

        bool CanMove = !Dead;

        if(Dead){
            if(WL.Math.Random.Fast_Bool(0.8f)){
                __Decals.Add((PlayerX - WorldX + WL.Math.Random.Fast_Int(-128, 128), PlayerY - WorldY + WL.Math.Random.Fast_Int(-128, 128), WL.Math.Random.Fast_Bool() ? T_Decal.One : T_Decal.Zero, TextureRotation.None));
            }

            Rotten += (float)TD.DeltaTimeS;
        }
        
        uint PlayerSize = (uint)(Texture_Player_Body.Width * 0.8f);
        int PlayerOffset = (int)((Texture_Player_Body.Width - PlayerSize) / 2);
        
        if(CanMove){
            uint PlayerSpeed = (uint)(WL.Math.Max(1, (float)TD.DeltaTimeS * 100 * (KeyPressed(Key.Shift) ? 1.5f : (KeyPressed(Key.Control) ? 0.3f : 1))));
            if(Health < HealthSmall){ PlayerSpeed = (uint)(PlayerSpeed / 2); }

            bool D = KeyPressed(Key.D);
            bool A = KeyPressed(Key.A);
            bool W = KeyPressed(Key.W);
            bool S = KeyPressed(Key.S);
            MovingDirection = new Vector2I(A && D ? 0 : (A ? 1 : (D ? -1 : 0)), W && S ? 0 : (W ? 1 : (S ? -1 : 0)));

            Vector2F DesiredMove = new Vector2F();

            CollisionLayer WallMask = IgnoreColliders ? CollisionLayer.None : CollisionLayer.L1 | CollisionLayer.L5;
            if(MovingDirection.X != 0 && MovingDirection.Y != 0){
                for(uint i = 1; i <= PlayerSpeed; i++){
                    int TestX = (int)(PlayerX - MovingDirection.X * i + PlayerOffset);
                    int TestY = (int)(PlayerY - MovingDirection.Y * i + PlayerOffset);

                    Collider TestCollider = new Collider(TestX, TestY, PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, WallMask);

                    if(!Collision(TestCollider, out Collider? _)){
                        DesiredMove.X = MovingDirection.X * i;
                        DesiredMove.Y = MovingDirection.Y * i;
                    }else{
                        TestCollider.X = TestX;
                        TestCollider.Y = PlayerY + PlayerOffset;
                        if(!Collision(TestCollider, out Collider? _)){
                            DesiredMove.X = MovingDirection.X * i;
                            DesiredMove.Y = 0;
                        }else{
                            TestCollider.X = PlayerX + PlayerOffset;
                            TestCollider.Y = TestY;
                            if(!Collision(TestCollider, out Collider? _)){
                                DesiredMove.X = 0;
                                DesiredMove.Y = MovingDirection.Y * i;
                            }else{
                                break;
                            }
                        }

                        break;
                    }
                }
            }
            else{
                for(uint i = 1; i < PlayerSpeed + 1; i++){
                    if(!Collision(new Collider((int)(PlayerX - (MovingDirection.X * i) + PlayerOffset), PlayerY + PlayerOffset, PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, WallMask), out Collider? _)){
                        DesiredMove.X = MovingDirection.X * i;
                    }
                    else{
                        break;
                    }
                }

                for(uint i = 1; i < PlayerSpeed + 1; i++){
                    if(!Collision(new Collider(PlayerX + PlayerOffset, (int)(PlayerY - (MovingDirection.Y * i) + PlayerOffset), PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, WallMask), out Collider? _)){
                        DesiredMove.Y = MovingDirection.Y * i;
                    }
                    else{
                        break;
                    }
                }
            }

            WorldPosition += DesiredMove;

            if(DesiredMove.X != 0 || DesiredMove.Y != 0){
                Track();

                if(Collision(new Collider(PlayerX + PlayerOffset, PlayerY + PlayerOffset, PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, CollisionLayer.L2), out Collider? _)){
                    if(WL.Math.Random.Fast_Bool(0.5f)){
                        Damage((uint)(WL.Math.Random.Fast_0_1() * 5));
                    }
                }

                if(Collision(new Collider((int)(PlayerX + PlayerOffset - DesiredMove.X * 2), (int)(PlayerY + PlayerOffset - DesiredMove.Y * 2), PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, CollisionLayer.L5), out Collider? __PushedCollider)){
                    Vector2I PushedEntityIndex1 = __PushedCollider!.Value.Info2;
                    int PushedEntityIndex2 = __PushedCollider!.Value.Info3;
                    EntityKey Key = new EntityKey(PushedEntityIndex1, (uint)PushedEntityIndex2);
                    Entity PushedEntity = __Entities[Key];

                    int __X = (DesiredMove.X == 0 ? 0 : WL.Math.Sign(DesiredMove.X));
                    int __Y = (DesiredMove.Y == 0 ? 0 : WL.Math.Sign(DesiredMove.Y));
                    
                    int NewX = PushedEntity.X - __X;
                    int NewY = PushedEntity.Y - __Y;
                    
                    if(!Collision(new Collider(WorldX + NewX - __X * 2 + 2, WorldY + NewY - __Y * 2 + 2, 12, 12, 0, PushedEntityIndex1, 0, CollisionLayer.L5, WallMask), out Collider? _, true)){
                        PushedEntity.X = NewX;
                        PushedEntity.Y = NewY;
                        __Entities[Key] = PushedEntity;
                    }
                }
            }
        }
        
        if(Collision(new Collider((int)(PlayerX + PlayerOffset), PlayerY + PlayerOffset, PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, CollisionLayer.L3), out Collider? _)){
            if(WL.Math.Random.Fast_Bool(0.8f)){
                Damage((uint)(WL.Math.Random.Fast_0_1() * 20), Dead ? 16 : 0);
            }
        }
        
        if(Collision(new Collider((int)(PlayerX + PlayerOffset), PlayerY + PlayerOffset, PlayerSize, PlayerSize, 0, Vector2I.Zero, 0, CollisionLayer.L1, CollisionLayer.All), out Collider? Collider__)){
            InsideCollision = Collider__!.Value.Layer;
            CollisionInfo1  = Collider__!.Value.Info1;
            CollisionInfo2  = Collider__!.Value.Info2;
            CollisionInfo3  = Collider__!.Value.Info3;
        }else{
            InsideCollision = CollisionLayer.None;
            CollisionInfo1  = 0;
            CollisionInfo2  = Vector2I.Zero;
            CollisionInfo3  = 0;
        }
    }

    private readonly List<(int, int, T_Decal, TextureRotation)> __Decals = [];
    private void Track(){
        if(WL.Math.Random.Fast_Bool(0.1f)){
            if(Health < HealthSmall){
                SplatBlood(PlayerX - WorldX, PlayerY - WorldY);
            }else{
                __Decals.Add((PlayerX - WorldX + WL.Math.Random.Fast_Int(-5, 5), PlayerY - WorldY  + WL.Math.Random.Fast_Int(-5, 5), T_Decal.Track, TextureRotation.None));
            }
        }
    }

    private void SplatBlood(int X, int Y){
        __Decals.Add((X, Y, T_Decal.Blood, WL.Math.Random.Fast_Bool(0.5f) ? (WL.Math.Random.Fast_Bool(0.5f) ? TextureRotation.None :  TextureRotation.Rotate90) : (WL.Math.Random.Fast_Bool(0.5f) ? TextureRotation.Rotate180 : TextureRotation.Rotate270)));
    }

    private void SetBlock(Block Block__, bool SnapToGrid = true, bool IgnoreEntities = false, bool Replace = true){
        if(SnapToGrid){
            Block__.X *= 16;
            Block__.Y *= 16;
        }

        Vector2I Key = new Vector2I(Block__.X, Block__.Y);
        if(__Blocks.ContainsKey(Key)){
            if(Block__.ID == T_Block.Empty){
                __Blocks.Remove(Key);
            }else{
                if(Replace){
                    Block OldBlock = __Blocks[Key];
                    if(OldBlock.ID != Block__.ID){
                        __Blocks[Key] = Block__;
                    }
                }
            }
        }else{
            if(Block__.ID != T_Block.Empty){
                __Blocks[Key] = Block__;
            }
        }

        if(!IgnoreEntities && BlockInfo_Solid(Block__.ID)){
            if(__Entities.ContainsKey(new EntityKey(Key))){ SetEntity(new Entity{ X = Block__.X, Y = Block__.Y }, false, true); }
        }
    }
    private readonly Dictionary<Vector2I, Block> __Blocks = [];

    private Block GetBlock(int X, int Y, bool SnapToGrid = true){
        if(SnapToGrid){
            X *= 16;
            Y *= 16;
        }
        return __Blocks.GetValueOrDefault(new Vector2I(X, Y), new Block{ ID = T_Block.Empty, X = X, Y = Y });
    }

    private void ClearAllScene(){
        __Blocks.Clear();
    }
    
    private void AddScene(string SceneMap, int X = 0, int Y = 0, uint __Seed = 0, bool Replace = false){
        try{
            if(string.IsNullOrEmpty(SceneMap)){ return; }
            
            int X__ = X;
            int Y__ = Y;
            
            uint Seed1__ = __Seed + 1222;
            uint Seed2__ = __Seed + 6848;
            
            foreach(char C in SceneMap){
                T_Block ID;
                switch(C){
                    case '\r': 
                        continue;
                    case '.':
                        X__++;
                        continue;
                    case '\n':
                        Y__++;
                        X__ = X;
                        continue;
                    case '#':
                        ID = T_Block.Metal;
                        break;
                    case '\'':
                        ID = T_Block.Ground_Planks;
                        break;
                    case 'A':
                        ID = T_Block.Ground_Asphalt;
                        break;
                    case 'B':
                        ID = T_Block.Bricks;
                        break;
                    case 'S':
                        ID = T_Block.Ground_Sand;
                        break;
                    case 'W':
                        ID = T_Block.Water;
                        break;
                    case 'b':
                        ID = T_Block.Black;
                        break;
                    case '^':
                        ID = T_Block.Ground_Grass;
                        break;
                    case 'Д':
                        Seed1__ += 121;
                        ID = WL.Math.Random.Fast_Bool(0.5f, ref Seed1__) ? T_Block.Ground_Grass  : T_Block.Empty;
                        break;
                    default:
                        ID = T_Block.Error;
                        break;
                }

                if(ID != T_Block.Empty){
                    SetBlock(new Block{ X = X__, Y = Y__, ID = ID}, Replace: Replace);
                }
                
                X__++;
            }
        }catch(Exception e){
            throw new Exception("Произошла ошибка при загрузке сцены!", e);
        }
    }

    private bool BlockInfo_Solid(T_Block B) => B is T_Block.Black or T_Block.Bricks or T_Block.Metal or T_Block.Water or T_Block.Error;
    
    private void SetEntity(Entity Entity__, bool SnapToGrid = true, bool IgnoreBlocks = false, bool Replace = true){
        if(SnapToGrid){
            Entity__.X *= 16;
            Entity__.Y *= 16;
        }

        bool HasUniqueID = Entity__.ID is T_Entity.Crate or T_Entity.Item or T_Entity.Mob_Spider;
        
        EntityKey Key = new EntityKey(new Vector2I(Entity__.X, Entity__.Y), HasUniqueID);
        
        if(!IgnoreBlocks){
            if(__Blocks.TryGetValue(Key.Position, out Block __Found) && BlockInfo_Solid(__Found.ID)){ return; }
        }

        if(Entity__.ID == T_Entity.Item && Entity__.Info == (byte)T_Item.Empty){
            Entity__.Info = (byte)T_Item.FirstAidKit;
        }
        
        if(__Entities.ContainsKey(Key)){
            if(Entity__.ID == T_Entity.Empty){
                __Entities.Remove(Key);
            }
            else{
                Entity OldEntity = __Entities[Key];
                if(OldEntity.ID != Entity__.ID){
                    __Entities[Key] = Entity__;
                }
            }
        }else{
            if(Entity__.ID != T_Entity.Empty){
                __Entities[Key] = Entity__;
            }
        }
    }
    private readonly Dictionary<EntityKey, Entity> __Entities = [];
    
    private void ClearAllEntityScene(){
        __Entities.Clear();
    }
    
    private void AddEntityScene(string SceneMap, int X = 0, int Y = 0, uint __Seed = 0, bool Replace = false){
        try{
            if(string.IsNullOrEmpty(SceneMap)){ return; }
            
            int X__ = X;
            int Y__ = Y;

            uint Seed1__ = __Seed;
            uint Seed2__ = __Seed + 999696;
            uint Seed3__ = __Seed + 993;
            
            foreach(char C in SceneMap){
                T_Entity ID;
                switch(C){
                    case '\r': 
                        continue;
                    case '.':
                        X__++;
                        continue;
                    case '\n':
                        Y__++;
                        X__ = X;
                        continue;
                    case 'C':
                        ID = T_Entity.Chair;
                        break;
                    case 'T':
                        ID = T_Entity.Table;
                        break;
                    case '^':
                        ID = T_Entity.Spikes;
                        break;
                    case 's':
                        ID = T_Entity.Mob_Spider;
                        break;
                    case '!':
                        ID = T_Entity.Tree;
                        break;
                    case '#':
                        ID = T_Entity.Crate;
                        break;
                    case '~':
                        ID = T_Entity.Grass;
                        break;
                    case '3':
                        ID = T_Entity.Bush;
                        break;
                    case 'Д':
                        Seed1__ += 1667;
                        Seed2__ += 551;
                        if(GetBlock(X__, Y__).ID == T_Block.Ground_Sand){
                            ID = WL.Math.Random.Fast_Bool(0.01f, ref Seed1__) ? T_Entity.Grass : T_Entity.Empty;
                        }else{
                            ID = WL.Math.Random.Fast_Bool(0.2f, ref Seed1__) ? T_Entity.Tree : (WL.Math.Random.Fast_Bool(0.4f, ref Seed2__) ? (WL.Math.Random.Fast_Bool(0.1f, ref Seed3__) ? T_Entity.Bush : T_Entity.Grass) : T_Entity.Empty);
                        }
                        break;
                    case 'д':
                        Seed1__ += 1532;
                        if(GetBlock(X__, Y__).ID == T_Block.Ground_Sand){
                            ID = WL.Math.Random.Fast_Bool(0.01f, ref Seed1__) ? T_Entity.Grass : T_Entity.Empty;
                        }else{
                            ID = WL.Math.Random.Fast_Bool(0.4f, ref Seed1__) ? (WL.Math.Random.Fast_Bool(0.1f, ref Seed1__) ? T_Entity.Bush : T_Entity.Grass) : T_Entity.Empty;
                        }
                        break;
                    default:
                        ID = T_Entity.Error;
                        break;
                }

                if(ID != T_Entity.Empty){
                    SetEntity(new Entity{ X = X__, Y = Y__, ID = ID}, Replace: Replace);
                }

                X__++;
            }
        }catch(Exception e){
            throw new Exception("Произошла ошибка при загрузке Entity сцены!", e);
        }
    }

    private struct EntityKey{
        public EntityKey(Vector2I Position, bool HasUniqueID = false){
            this.Position = Position;
            UniqueID = HasUniqueID ? __TotalUniqueID++ : 0;
        }
        
        public EntityKey(Vector2I Position, uint UniqueID){
            this.Position = Position;
            this.UniqueID = UniqueID;
        }
        
        public readonly Vector2I Position;
        public readonly uint     UniqueID;
    }
    private static uint __TotalUniqueID = 1;
    
    private void SpawnItem(int X, int Y, T_Item Item){
        SetEntity(new Entity{ X = X, Y = Y, ID = T_Entity.Item, Info = (byte)Item}, false);
    }

    public enum RenderableType{
        Tile  = 0,
        Tiles = 1
    }
    
    private readonly List<Renderable> RenderQueue = [];
    public struct Renderable{
        public Renderable(){}
        
        public int             X             = 0;
        public int             Y             = 0;
        public uint            W             = 0;
        public uint            H             = 0;
        public Palette         Palette       = Palette_World;
        public Texture         Texture       = Texture_Black;
        public TextureRotation Rotation      = TextureRotation.None;
        public RenderableType  Type          = RenderableType.Tile;
        public int             Z             = 0;
        public bool            FlipX         = false;
        public bool            FlipY         = false;
        public ColorB?         MultiplyColor = null;
    }
    
    private float BlinkTimer     = 0;
    private float AnimationTimer = 0;
    private bool  PlayerFlipped  = false;
    private float WorldDeltaTick = 0;
    public override void Render(TickData TD, Image.ImageContext C){
        float DTS = StopTime ? 0 : (float)TD.DeltaTimeS;
        if(!Dead){ LastHealed -= DTS; }
        WorldDeltaTick += DTS;
        AnimationTimer += DTS;
        if(AnimationTimer > 1){ AnimationTimer = 0; }
        
        void Button(byte ButtonID, string ButtonText, int X, int Y, bool Always = false){
            if(MenuSelectedButton == ButtonID || Always){
                RenderOutlineColorText(C, ButtonText, X, Y, ColorB.White, ColorB.Red);
            }else{
                RenderColorText(C, ButtonText, X, Y, ColorB.Black);   
            }
        }
        
        if(InMainMenu){
            Texture_GOLU.RenderTiles(C, Palette_Default, -(int)(WL.Math.DCos((float)TD.DeltaTick / 2) * 128), -(int)(WL.Math.DSin((float)TD.DeltaTick / 2) * 128), 3, 3, MultiplyColor: ColorB.White.SetA(64));
            
            C.Border(0, 0, C.Width, C.Height, 1, ColorB.Black);
            
            if(Interface == T_Interface.None){
                Texture_Author.Render(C, Palette_Default, (int)(C.Width - Texture_Author.Width) - 3, (int)(C.Height - Texture_Author.Height) - 3);
                Font.Render(C, Palette_Default, Version, 3, (int)(C.Height - 8 - 3));

                void RenderGOLU(float SinOffset, ColorB MultiplyColor){
                    Texture_G.Render(C, Palette_Default, (int)(C.Width/2 - Texture_G.Width/2 - Texture_G.Width*1.5F), 30 + (byte)(WL.Math.DSin((float)TD.DeltaTick * 2 + SinOffset) * 10), MultiplyColor: MultiplyColor);
                    Texture_O.Render(C, Palette_Default, (int)(C.Width/2 - Texture_G.Width/2 - Texture_G.Width/2), 30 + (byte)(WL.Math.DSin((float)TD.DeltaTick * 2 + 1 + SinOffset) * 10), MultiplyColor: MultiplyColor);
                    Texture_L.Render(C, Palette_Default, (int)(C.Width/2 - Texture_G.Width/2 + Texture_G.Width/2), 30 + (byte)(WL.Math.DSin((float)TD.DeltaTick * 2 + 2 + SinOffset) * 10), MultiplyColor: MultiplyColor);
                    Texture_U.Render(C, Palette_Default, (int)(C.Width/2 - Texture_G.Width/2 + Texture_G.Width*1.5F), 30 + (byte)(WL.Math.DSin((float)TD.DeltaTick * 2 + 3 + SinOffset) * 10), MultiplyColor: MultiplyColor);
                }
                RenderGOLU(-0.2f, ColorB.Black.SetA((byte)(255 * 0.2f)));
                RenderGOLU(-0.4f, ColorB.Black.SetA((byte)(255 * 0.2f)));
                RenderGOLU(-0.6f, ColorB.Black.SetA((byte)(255 * 0.2f)));
                RenderGOLU(-0.8f, ColorB.Black.SetA((byte)(255 * 0.2f)));
                RenderGOLU(0, ColorB.White);

                C.Fill((int)(C.Width / 2 - Texture_G.Width / 2 - Texture_G.Width * 1.5F), 75, 127, 2, ColorB.Black);
                
                Texture_Title.Render(C, Palette_Default, (int)(C.Width/2 - Texture_Title.Width/2), 80);
                
                Button(0, "ЗАГРУЗИТЬ", (int)(C.Width / 2 - Font.TextSize("ЗАГРУЗИТЬ").X / 2), 150 + (0 * 13));
                Button(1, "НОВАЯ", (int)(C.Width / 2 - Font.TextSize("НОВАЯ").X / 2), 150 + (1 * 13));
                Button(2, "ПОМОЩЬ", (int)(C.Width / 2 - Font.TextSize("ПОМОЩЬ").X / 2), 150 + (2 * 13));
                Button(3, "ВЫЙТИ", (int)(C.Width / 2 - Font.TextSize("ВЫЙТИ").X / 2), 150 + (3 * 13));
            }else if(Interface == (T_Interface)1){
                string[] HelpInfo = [
                    "[W,S,A,D] - ДВИЖЕНИЕ",
                    "[SHIFT] - БЕГ",
                    "[CONTROL] - КРАСТЬСЯ",
                    "[E] - ВЗАИМОДЕЙСТВОВАТЬ",
                    "[BACKSPACE] - ВЫБРОСИТЬ",
                    "[TAB] - ИНВЕНТАРЬ",
                    "[1-9] ВЫБРАТЬ СЛОТ",
                    "[ENTER,SPACE] - ВЫПОЛНИТЬ",
                    "[ESC] - ВЫХОД",
                    "[C] - ПОКАЗАТЬ КОЛЛАЙДЕРЫ",
                    "[I] - БЕССМЕРТИЕ iс",
                    "[X] - ИГНОРИРОВАТЬ КОЛЛАЙДЕРЫ",
                    "[HOME] - ТЕЛЕПОРТ В ЦЕНТР",
                    "[F1,F2] - ТЕСТОВОЕ",
                    "",
                    "[ДВИЖЕНИЕ + SHIFT] - ДВИГАТЬ ПРЕДМЕТЫ\nВ ИНВЕНТОРЕ"
                ];

                for(int i = 0; i < HelpInfo.Length; i++){
                    string HelpInfoMessage = HelpInfo[i];
                    
                    Font.Render(C, Palette_Default, HelpInfoMessage, 30, 15 + i * 12);
                }
                
                Button(0, "ОБРАТНО", (int)(C.Width / 2 - Font.TextSize("ОБРАТНО").X / 2), 150 + (5 * 13), true);
            }
            
            return;
        }

        RenderQueue.Clear();
        
        const int RenderLayer_Bottom = -10000000;
        int RenderLayer_Object(int Y) => -100000 + (Y * 100);
        int RenderLayer_Top(int Y) => 1000 + (Y * 100);

        void AddToRender(Renderable R){
            int OFFSET = 5 * 16;
            int LEFT_BORDER = -OFFSET;
            int RIGHT_BORDER = (int)C.Width + OFFSET;
            int TOP_BORDER = -OFFSET;
            int BOTTOM_BORDER = (int)C.Height + OFFSET;

            int X = R.X;
            int Y = R.Y;
            
            if(!(X < LEFT_BORDER || X > RIGHT_BORDER || Y < TOP_BORDER || Y > BOTTOM_BORDER)){
                RenderQueue.Add(R);
            }
        }
        
        int __OffsetX = WorldX % 16;
        int __OffsetY = WorldY % 16;
        if(__OffsetX < 0){ __OffsetX += 16; }
        if(__OffsetY < 0){ __OffsetY += 16; }
        for(int Y__ = -1; Y__ < 16; Y__++){
            for(int X__ = -1; X__ < 16; X__++){
                int __X = X__ * 16 + __OffsetX;
                int __Y = Y__ * 16 + __OffsetY;
                AddToRender(new Renderable{ Texture = Texture_Ground, X = __X, Y = __Y, Z = RenderLayer_Bottom });
            }
        }
        
        foreach(Block Block in __Blocks.Values){
            if(Block.ID is T_Block.Ground_Planks or T_Block.Ground_Asphalt or T_Block.Ground_Sand or T_Block.Water or T_Block.Ground_Grass){
                Texture BlockTexture = Block.ID switch{
                    T_Block.Ground_Planks  => Texture_Planks,
                    T_Block.Ground_Asphalt => Texture_Asphalt,
                    T_Block.Ground_Sand    => Texture_Sand,
                    T_Block.Water          => (__Blocks.TryGetValue(new Vector2I(Block.X, Block.Y - 16), out Block __Found) && __Found.ID == Block.ID ? Texture_Water : Texture_Water_Top),
                    T_Block.Ground_Grass   => Texture_Grass,
                };
                
                AddToRender(new Renderable{Texture = BlockTexture, X = WorldX + Block.X, Y = WorldY + Block.Y, Z = RenderLayer_Bottom + 1});
            }
            
            if(Block.ID is T_Block.Metal or T_Block.Bricks or T_Block.Black or T_Block.Error){
                Texture BlockTexture = Block.ID switch{
                    T_Block.Metal  => Texture_Metal,
                    T_Block.Bricks => Texture_Bricks,
                    T_Block.Black  => Texture_Black,
                    T_Block.Error  => Texture_Debug
                };
                
                AddToRender(new Renderable{ Texture = BlockTexture, X = WorldX + Block.X, Y = WorldY + Block.Y, Z = RenderLayer_Object(Block.Y)});
            }
        }

        foreach((int, int, T_Decal, TextureRotation) Track in __Decals){
            Texture DecalTexture = Track.Item3 switch{
                T_Decal.Track => Texture_Track,
                T_Decal.Blood => Texture_Blood,
                T_Decal.Zero  => Texture_Zero,
                T_Decal.One   => Texture_One
            };
            
            AddToRender(new Renderable{ Texture = DecalTexture, Palette = Palette_Default, X = WorldX + Track.Item1, Y = WorldY + Track.Item2, Rotation = Track.Item4, Z = RenderLayer_Bottom + 2});
        }
        
        foreach(Entity Entity in __Entities.Values){
            if(Entity.ID is T_Entity.Chair or T_Entity.Table or T_Entity.Spikes or T_Entity.Tree or T_Entity.Item or T_Entity.Crate or T_Entity.Grass or T_Entity.Bush or T_Entity.Error){
                Texture EntityTexture = Entity.ID switch{
                    T_Entity.Chair  => Texture_Chair,
                    T_Entity.Table  => Texture_Table,
                    T_Entity.Spikes => Texture_Spikes,
                    T_Entity.Tree   => Texture_Tree,
                    T_Entity.Item   => ItemTexture((T_Item)Entity.Info),
                    T_Entity.Crate  => Texture_Crate,
                    T_Entity.Grass  => Texture_TallGrass,
                    T_Entity.Bush   => Texture_Bush,
                    T_Entity.Error  => Texture_Debug
                };

                bool __Top = false;
                if(Entity.ID is T_Entity.Crate){
                    __Top = true;
                }
                
                int OffsetX = 0;
                int OffsetY = 0;
                if(Entity.ID == T_Entity.Tree){
                    OffsetY = -48;
                }

                if(Entity.ID is T_Entity.Grass or T_Entity.Bush){
                    OffsetX = (int)(WL.Math.Sin(WorldDeltaTick * 2 + (Entity.X * 2 + Entity.Y)) * 2);
                }

                bool BottomRenderLayer = Entity.ID is T_Entity.Spikes;

                AddToRender(new Renderable{ Texture = EntityTexture, Palette = Palette_Default, X = WorldX + Entity.X + OffsetX, Y = WorldY + Entity.Y + OffsetY, Rotation = Entity.Rotation, Z = (BottomRenderLayer ? RenderLayer_Bottom + 3 : RenderLayer_Object(Entity.Y) + (__Top ? 1 : 0))});

                if(Entity.ID == T_Entity.Tree){
                    void __RenderLeaves(int X__, int Y__){
                        int __X__ = -16;
                        int __Y__ = -64;

                        __X__ += (X__ - 1) * (X__ == 0 ? 16 : 8);
                        __Y__ += (Y__ - 1) * (Y__ == 0 ? 8 : 16);

                        __X__ += (int)(WL.Math.Sin(WorldDeltaTick * 2 + (Entity.X + __X__) * 432) * 2);
                        __Y__ += (int)(WL.Math.Sin(WorldDeltaTick * 2 + (Entity.Y + __Y__) * 12) * 2);
                        AddToRender(new Renderable{ Texture = Texture_Tree_Leaves, Palette = Palette_Default, X = WorldX + Entity.X + __X__, Y = WorldY + Entity.Y + __Y__, Rotation = Entity.Rotation, Z = RenderLayer_Object(Entity.Y) + (X__ + Y__)});
                    }
                    __RenderLeaves(0, 0);
                    __RenderLeaves(2, 0);
                    __RenderLeaves(1, 2);
                }
            }
            
            if(Entity.ID is T_Entity.Mob_Spider){
                Texture EntityTexture = Entity.ID switch{
                    T_Entity.Mob_Spider => (AnimationTimer > 0.5f ? Texture_Spider_Anim : Texture_Spider)
                };

                int OffsetX = 0;
                int OffsetY = 0;

                if(Entity.ID == T_Entity.Mob_Spider){
                    OffsetX = 8;
                    OffsetY = 8;
                }
                
                AddToRender(new Renderable{ Texture = EntityTexture, Palette = Palette_Default, X = WorldX + Entity.X - OffsetX, Y = WorldY + Entity.Y - OffsetY, Rotation = Entity.Rotation, Z = RenderLayer_Top(Entity.Y)});
            }
        }

        T_Item Item = Inventory[SelectedItem];
        
        void RenderPlayer(){
            Texture PlayerBody  = Texture_Player_Body;
            Texture PlayerEyes  = Texture_Player_Eyes;
            Texture PlayerNose  = Texture_Player_Nose;
            Texture PlayerMouth = (Dead ? Texture_Player_Mouth : Emotion_Happiness < 25 ? Texture_Player_Mouth_Sad : (Emotion_Happiness > 75 ? Texture_Player_Mouth_Happy : Texture_Player_Mouth));
            BlinkTimer += DTS;

            if(BlinkTimer > 3 || Dead){
                PlayerEyes = Texture_Player_Eyes_Blink;
                if(BlinkTimer > 3.25f){
                    BlinkTimer = 0;
                }
            }
        
            if(MovingDirection.X != 0){
                PlayerFlipped = MovingDirection.X > 0;
            }
            
            int __PlayerZ = 0;
            void __RenderPlayerPart(Texture T, ColorB? Color, int OffsetY = 0){
                AddToRender(new Renderable{ Texture = T, Palette = Palette_Default, X = PlayerX, Y = PlayerY + OffsetY, FlipX = PlayerFlipped, MultiplyColor = Color, Z = RenderLayer_Object(PlayerY - WorldY + 1) + __PlayerZ});
                __PlayerZ++;
            }
            
            if(Item != T_Item.Empty){
                __RenderPlayerPart(ItemTexture(Item), null, -11);
            }
        
            ColorB PlayerColor = ColorB.Lerp(ColorB.White, ColorB.DarkRed, WL.Math.Clamp01((Rotten - 2) / 50));
            
            __RenderPlayerPart(PlayerBody, PlayerColor);
            __RenderPlayerPart(PlayerNose, PlayerColor);
            __RenderPlayerPart(PlayerMouth, PlayerColor);
            __RenderPlayerPart(PlayerEyes, PlayerColor);

            if(Health < HealthSmall * 2){
                Texture PlayerBlood = Health < HealthSmall ? Texture_Player_Blood_Strong : Texture_Player_Blood;
                __RenderPlayerPart(PlayerBlood, ColorB.Lerp(ColorB.White, ColorB.DarkGreen, WL.Math.Clamp01((Rotten - 2) / 50)));
            }
        
            if(LastHealed > 0){
                __RenderPlayerPart(Texture_Player_Healed, null);
            }
        }
        RenderPlayer();

        RenderQueue.Sort((A, B) => A.Z.CompareTo(B.Z));
        foreach(Renderable R in RenderQueue){
            switch(R.Type){
                case RenderableType.Tile: R.Texture.Render(C, R.Palette, R.X, R.Y, FlipX: R.FlipX, FlipY: R.FlipY, MultiplyColor: R.MultiplyColor, Rotation: R.Rotation); break;
                case RenderableType.Tiles: R.Texture.RenderTiles(C, R.Palette, R.X, R.Y, R.W, R.H); break;
            }
        }
        
        byte PerlinNoise(int X, int Y, float Scale = 1) => Texture_PerlinNoise.GetPixelRepeat(Palette_Default, X, Y, Scale).R;

        byte Light(float TX, float TY) => Texture_Light.GetPixelRepeat(Palette_Alpha, (int)(TX * Texture_Light.Width), (int)(TY * Texture_Light.Height)).A;
        
        void PostProcessing(){
            Vector2F DayCycle_Moring = new Vector2F(0, 50);
            Vector2F DayCycle_Noon  = new Vector2F((float)C.Width/2, 25);
            Vector2F DayCycle_Eving = new Vector2F(C.Width, 50);

            Vector2F SunPosition;
            float DayAlpha;
            switch(Time){
                case >= 6 and < 12:
                    DayAlpha = (Time - 6) / 6f;
                    SunPosition = Vector2F.Lerp(DayCycle_Moring, DayCycle_Noon, DayAlpha);
                    break;
                case >= 12 and < 18:
                    DayAlpha = (Time - 12) / 6f;
                    SunPosition = Vector2F.Lerp(DayCycle_Noon, DayCycle_Eving, DayAlpha);
                    DayAlpha = 1 - DayAlpha;
                    break;
                default:
                    DayAlpha = 0;
                    SunPosition = Vector2F.Zero;
                    break;
            }
            
            float NightAlpha;
            if(DayAlpha > 0){
                NightAlpha = 0;
            }else{
                if(Time >= 18f){
                    NightAlpha = 1 - (24f - Time) / 6f;
                }else{
                    NightAlpha = 1f - Time / 6f;
                }
            }
            
            const float SunRadius = 300;

            List<(int, int, Texture, Palette, ColorB)> WaterTextures = [((int)SunPosition.X, (int)SunPosition.Y, Texture_Circle_16px, Palette_Alpha, new ColorB(255, 255, 255, (byte)(DayAlpha * 255)))];
            
            for(uint FY = 0; FY < C.Height; FY++){
                for(uint FX = 0; FX < C.Width; FX++){
                    ColorB Color = C[FX, FY];
                    ColorB? Result = null;

                    int PX = PlayerX - WorldX - ((int)C.Width /2 - (int)FX);
                    int PY = PlayerY - WorldY - ((int)C.Height/2 - (int)FY);
                    
                    if(Color == __WaterShaderColor || Color == __WaterShaderColor_Dark){
                        byte __Noise1 = PerlinNoise((int)(PX + WorldDeltaTick * 2), (int)(PY + WorldDeltaTick * 4));
                        byte __Noise2 = PerlinNoise((int)(PX + 64 + WorldDeltaTick * -3), (int)(PY + 64 + WorldDeltaTick * 2), 2);
                        byte __Noise3 = PerlinNoise((int)((FX/1.5f + PX/4f) + 32 + WorldDeltaTick), (int)((FY/1.5f + PY/4f) + 32 - WorldDeltaTick), 4);

                        ColorB WaterSolid = new ColorB(WL.Math.ClampByteB((byte)((__Noise1 / 8 + __Noise2 / 8) + 70)), 0, 0);

                        WaterSolid += new ColorB((byte)(Texture_WaterNoise.GetPixelRepeat(Palette_Default, (int)(PX + WorldDeltaTick * -4), (int)(PY + WorldDeltaTick * -5)).R / 8));

                        WaterSolid += new ColorB(__Noise3, (byte)(__Noise3 / 2), (byte)(__Noise3 / 2));

                        if(DayAlpha > 0){
                            ColorB SunColor = new ColorB(255, 255, 200, (byte)(Light((FX - SunPosition.X + SunRadius) / (SunRadius * 2), (FY - SunPosition.Y + SunRadius) / (SunRadius * 2)) * DayAlpha));
                            Result = ColorB.BlendAlpha(WaterSolid, SunColor);
                        }else{
                            Result = WaterSolid;
                        }

                        foreach((int TX, int TY, Texture Texture, Palette Palette, ColorB MultiplyColor) in WaterTextures){
                            int LocalX = (int)FX - TX + (int)Texture.Width  / 2;
                            int LocalY = (int)FY - TY + (int)Texture.Height / 2;

                            if(LocalX >= 0 && LocalX < Texture.Width && LocalY >= 0 && LocalY < Texture.Height){
                                Result = ColorB.BlendAlpha(Result ?? WaterSolid, Texture.GetPixelRepeat(Palette, LocalX, LocalY) * MultiplyColor);
                            }
                        }

                        if(Color == __WaterShaderColor_Dark){ Result -= new ColorB(64, 64, 64); }
                    }

                    if(PX <= -LevelSizeTile.X || PX >= LevelSizeTile.X || PY <= -LevelSizeTile.Y || PY >= LevelSizeTile.Y){
                        int DistanceX = 0;
                        int DistanceY = 0;

                        if(PX < -LevelSizeTile.X){ DistanceX = -(int)LevelSizeTile.X - PX; }
                        else if(PX > LevelSizeTile.X){ DistanceX = PX - (int)LevelSizeTile.X; }
                    
                        if(PY < -LevelSizeTile.Y){ DistanceY = -(int)LevelSizeTile.Y - PY; }
                        else if(PY > LevelSizeTile.Y){ DistanceY = PY - (int)LevelSizeTile.Y; }

                        int Distance = WL.Math.MaxI(DistanceX, DistanceY);

                        const int FadeDistance = 128;

                        Result = ColorB.BlendAlpha(Result ?? Color, new ColorB((byte)WL.Math.Random.Fast_Int(128, 255), 0, 0, (byte)(WL.Math.Clamp01((float)Distance / FadeDistance) * 255)));
                    }

                    if(DayAlpha == 0){
                        Result = ColorB.BlendAlpha(Result ?? Color, new ColorB(0, 0, 0, (byte)(NightAlpha * 192)));
                    }
                    
                    if(Result.HasValue){ C.SetPixel(FX, FY, Result.Value); }
                }   
            }
        }
        PostProcessing();
        
        if(RenderColliders){ RenderColliders(C); }

        if(InsideCollision == CollisionLayer.L4){
            T_Item ItemOnGround = (T_Item)CollisionInfo1;
            if(ItemOnGround != T_Item.Empty){
                Entity ItemOnGroundEntity = __Entities[new EntityKey(CollisionInfo2, (uint)CollisionInfo3)];
                string ItemName__ = ItemName(ItemOnGround);
                Vector2U ItemNameSize__ = Font.TextSize(ItemName__);
                int X__ = ItemOnGroundEntity.X + WorldX - (int)(ItemNameSize__.X / 2) + (16 / 2);
                int Y__ = ItemOnGroundEntity.Y + WorldY;
                C.Fill(X__ - 1, Y__ - 1, ItemNameSize__.X + 2, ItemNameSize__.Y + 2, ColorB.White.SetA(192), ImageBlend.Alpha);
                C.Border(X__ - 2, Y__ - 2, ItemNameSize__.X + 4, ItemNameSize__.Y + 4, 1, ColorB.White);
                Font.Render(C, Palette_Default, ItemName__, X__, Y__);
            }
        }
        
        void RenderThoughts(int X, int Y){
            if(string.IsNullOrWhiteSpace(Thoughts)){ return; }
            Vector2U ThoughtsSize = Font.TextSize(Thoughts);
            int X__ = (int)(X - ThoughtsSize.X / 2);
            uint Height__ = ThoughtsSize.Y + 14;
            Texture_Cloud.Render9Slice(C, Palette_Default, 10, X__, Y - (int)Height__, ThoughtsSize.X + 16, Height__);
            
            RenderOutlineColorText(C, Thoughts, X__ + 9, Y + 8 - (int)Height__, ColorB.Black, ColorB.White);
        }
        RenderThoughts(PlayerX, PlayerY - 8 - (int)(WL.Math.Sin(WorldDeltaTick) * 3));

        if(Interface is T_Interface.None or T_Interface.Menu && !Dead){
            if(Item == T_Item.GPS){
                void RenderMap(){
                    Vector2I __RenderCenterPanel(uint Size, ColorB Color){
                        int __X = (int)(C.Width  - Size) / 2;
                        int __Y = (int)(C.Height - Size) / 2;
                        C.Fill(__X, __Y, Size, Size, Color);
                        return new Vector2I(__X, __Y);
                    }
                    const uint MapSize = 180;
                    
                    Vector2I MapOffset = __RenderCenterPanel(MapSize, WorldBackgroundColor);

                    void __MapPixel(int X__, int Y__, ColorB Color, bool Fixed = false){
                        uint __X = (uint)MapOffset.X;
                        uint __Y = (uint)MapOffset.Y;

                        if(!Fixed){
                            X__ += (int)WorldPosition.X;
                            Y__ += (int)WorldPosition.Y;
                            
                            X__ = (int)WL.Math.Floor((float)X__ / 16);
                            Y__ = (int)WL.Math.Floor((float)Y__ / 16);
                        }
                        
                        X__ += (int)MapSize / 2;
                        Y__ += (int)MapSize / 2;
                    
                        __X += (uint)X__;
                        __Y += (uint)Y__;   
                        
                        if(__X < MapOffset.X || __Y < MapOffset.Y || __X > MapOffset.X + MapSize - 1 || __Y > MapOffset.Y + MapSize - 1){ return; }
                        
                        C[__X, __Y] = Color;
                    }
                    
                    foreach(Block Block in __Blocks.Values){
                        ColorB BlockColor = Palette_World[MapBlocksColor.GetValueOrDefault(Block.ID, (byte)1)];
                        __MapPixel(Block.X, Block.Y, BlockColor);
                    }

                    foreach(Entity Entity in __Entities.Values){
                        byte __PaletteIndex = MapEntitiesColor.GetValueOrDefault(Entity.ID, (byte)0);
                        if(__PaletteIndex == 0){ continue; }
                        ColorB EntityColor = Palette_World[__PaletteIndex];
                        __MapPixel(Entity.X, Entity.Y, EntityColor);

                        if(Entity.ID == T_Entity.Tree){
                            __MapPixel(Entity.X, Entity.Y + 16, EntityColor);
                            __MapPixel(Entity.X, Entity.Y + 16 * 2, EntityColor);
                        }
                    }
                    
                    for(int __Y__ = -(int)MapSize/2; __Y__ < MapSize/2; __Y__++){
                        for(int __X__ = -(int)MapSize/2; __X__ < MapSize/2; __X__++){
                            int PX = PlayerX - WorldX + __X__ * 16;
                            int PY = PlayerY - WorldY + __Y__ * 16;

                            if(PX <= -LevelSizeTile.X || PX >= LevelSizeTile.X || PY <= -LevelSizeTile.Y || PY >= LevelSizeTile.Y){ __MapPixel(__X__, __Y__, new ColorB((byte)WL.Math.Random.Fast_Int(128, 255)), true); }
                        }   
                    }

                    void __MapPixelPlayer(int __X, int __Y) => __MapPixel(PlayerX - WorldX + __X * 16, PlayerY - WorldY + __Y * 16, ColorB.Blue);
                    __MapPixelPlayer(0, 1);
                    __MapPixelPlayer(0, 2);
                    __MapPixelPlayer(0, -1);
                    __MapPixelPlayer(0, -2);
                    __MapPixelPlayer(1, 0);
                    __MapPixelPlayer(2, 0);
                    __MapPixelPlayer(-1, 0);
                    __MapPixelPlayer(-2, 0);
                    
                    string Coordinates = CoordinatesX + " : " + CoordinatesY;
                    Vector2U __CoordinatesSize = Font.TextSize(Coordinates);
                    Font.Render(C, Palette_Default, Coordinates, (int)(MapOffset.X + MapSize) - (int)__CoordinatesSize.X - 2, (int)(MapOffset.Y + MapSize) - (int)__CoordinatesSize.Y - 2);
                    
                    Texture_GPS_Overlay.Render(C, Palette_Default);
                }
                RenderMap();
            }
        }
        
        void RenderUI(){
            float HealthPulse = Dead ? 0 : WL.Math.DSin(WorldDeltaTick / WL.Math.Sqr((float)Health / HealthMax));
            ColorB FrameColor = new ColorB((byte)(HealthPulse * 255), 0, 0);

            uint Thickness = (uint)WL.Math.Min(1 + HealthPulse / WL.Math.Sqr((float)Health / HealthMax), 16);
            
            C.Border(0, 0, C.Width, C.Height, 1, FrameColor);
            C.Border(1, 1, C.Width - 2, C.Height - 2, Thickness, FrameColor.Clone().SetA(128), ImageBlend.Alpha);
            C.Border(1 + (int)Thickness, 1 + (int)Thickness, C.Width - (1 + Thickness) * 2, C.Height - (1 + Thickness) * 2, Thickness, FrameColor.Clone().SetA(64), ImageBlend.Alpha);
            
            C.Fill(20 - 1, (int)C.Height - 16 - 1, HealthMax + 2, 8 + 2, ColorB.DarkRed);
            C.Fill(20, (int)C.Height - 16, HealthMax, 8, ColorB.Black);
            C.Fill(20, (int)C.Height - 16, Health, 8, ColorB.Red);
            C.Fill(20, (int)C.Height - 16 + 3, Health, 8 - 6, ColorB.LightRed);

            Font.Render(C, Palette_Default, Immortality ? "i" : Health.ToString(), 20, (int)C.Height - 16);
            
            Texture_Health.Render(C, Palette_Default, 3, (int)C.Height - 21);
            
            string __Text = (Item == T_Item.Empty ? "" : ItemName(Item)) + " [" + (SelectedItem + 1) + "]";
            Font.Render(C, Palette_Default, __Text, (int)C.Width - (int)Font.TextSize(__Text).X - 3, (int)C.Height - 8 - 3);

            void RenderSlot(Image.ImageContext C, byte ID, int X, int Y){
                int X__ = 20 + X * 36;
                int Y__ = 30 + Y * 36;
                C.Fill(X__, Y__, 34, 34, SelectedItem == ID ? ColorB.Lerp(ColorB.Gray, ColorB.Red, 0.5f) : ColorB.Gray);
                C.Fill(X__ + 4, Y__ + 4, 34 - 4 * 2, 34 - 4 * 2, ColorB.Black.SetA(64), ImageBlend.Alpha);
                C.Fill(X__ + 8, Y__ + 8, 34 - 8 * 2, 34 - 8 * 2, ColorB.Black.SetA(64), ImageBlend.Alpha);
                C.Fill(X__ + 12, Y__ + 12, 34 - 12 * 2, 34 - 12 * 2, ColorB.Black.SetA(64), ImageBlend.Alpha);
                C.Border(X__, Y__, 34, 34, 1, SelectedItem == ID ? ColorB.Red : ColorB.Black);

                if(SelectedItem == ID){
                    C.Border(X__ - 1, Y__ - 1, 34 + 2, 34 + 2, 1, ColorB.Red.SetA(128), ImageBlend.Alpha);
                }

                T_Item Item = Inventory[ID];
        
                if(Item != 0){
                    Texture ItemTexture = Item switch{
                        T_Item.FirstAidKit => Texture_FirstAidKit_Icon,
                        T_Item.GPS         => Texture_GPS_Icon,
                        
                        var _ => Texture_Debug
                    };
            
                    ItemTexture.Render(C, Palette_Default, X__ + 1, Y__ + 1);
                }
            }
            
            if(Interface != T_Interface.None){ C.Fill(ColorB.Black.SetA(128), ImageBlend.Alpha); }
            
            switch(Interface){
                case T_Interface.Inventory: {
                    C.Fill(10, 20, C.Width - 20, C.Height - 40);
                    C.Border(10, 20, C.Width - 20, C.Height - 40, 1, ColorB.Black);
                    
                    RenderSlot(C, 0, 0, 0);
                    RenderSlot(C, 1, 1, 0);
                    RenderSlot(C, 2, 2, 0);
                    RenderSlot(C, 3, 3, 0);
                    RenderSlot(C, 4, 4, 0);
                    RenderSlot(C, 5, 5, 0);
                    
                    RenderSlot(C, 6, 0, 1);
                    RenderSlot(C, 7, 1, 1);
                    RenderSlot(C, 8, 2, 1);
                    RenderSlot(C, 9, 3, 1);
                    RenderSlot(C, 10, 4, 1);
                    RenderSlot(C, 11, 5, 1);

                    C.Fill(20, 110, C.Width - 40, C.Height - 140, ColorB.Gray);
                    C.Border(20, 110, C.Width - 40, C.Height - 140, 1, ColorB.Black);
                    
                    if(Item != T_Item.Empty){
                        string Name = ItemName(Item);
                        
                        string Description = Item switch{
                            T_Item.FirstAidKit => "ЛЕЧИТ БЕДНЫЙ КУБИК ГУЛУ (+ с50)",
                            T_Item.GPS => "ЕСЛИ ДЕРЖАТЬ В РУКАХ,\nПОКАЗЫВАЕТ КАРТУ",
                            
                            var _ => "О БОЖЕ ЧТО ЭТО ТАКОЕ?"
                        };
                        
                        Font.Render(C, Palette_Default, "[" + (byte)Item + "] " + Name, 20 + 2, 110 + 2);
                        
                        C.Fill(20, 110 + 11, C.Width - 40, 1, ColorB.Black);
                        
                        Font.Render(C, Palette_Default, Description, 20 + 2, 110 + 2 + 11);
                    }
                    break;
                }
                case T_Interface.Menu:{
                    Button(0, "ПРОДОЛЖИТЬ",15, 120 + (0 * 13));
                    Button(1, "ВЫЙТИ",15, 120 + (1 * 13));
                    
                    break;
                }
            }
        }
        RenderUI();
    }
    
    private static Texture ItemTexture(T_Item Item){
        if(Item == T_Item.Empty){ throw new Exception("Указан пустой предмет, невозможно получить текстуру!"); }

        return Item switch{
            T_Item.FirstAidKit => Texture_FirstAidKit,
            T_Item.GPS         => Texture_GPS,
            
            var _ => Texture_Debug
        };
    }

    private static string ItemName(T_Item Item){
        if(Item == T_Item.Empty){ throw new Exception("Указан пустой предмет, невозможно получить его название!"); }
        
        return Item switch{
            T_Item.FirstAidKit => "АПТЕЧКА",
            T_Item.GPS         => "GPS",
            
            var _ => "ПРЕДМЕТ [" + (byte)Item + "]"
        };
    }

    public override ColorB BackgroundColor(){
        return WorldBackgroundColor;
    }

    private void StartLevel(T_Level Level){
        ClearAllEntityScene();
        ClearAllScene();

        __Decals.Clear();

        Interface = T_Interface.None;
        
        WorldPosition = Vector2F.Zero;
        
        WorldDeltaTick = 0;

        if(Level == T_Level.Calm){
            GenerateLevel(Level);
        }
    }

    private void GoToMainMenu(){
        StartLevel(T_Level.None);
        
        InMainMenu = true;
        Interface = T_Interface.None;
        MenuSelectedButton = 0;
    }
    
    private void StartGame(){
        InMainMenu = false;
        
        WorldPosition = Vector2F.Zero;
        __Decals.Clear();

        Health = HealthMax;
        Interface = 0;

        SelectedItem = 0;

        LastHealed = 0;
        Rotten = 0;

        Thoughts = "";
        ThoughtsTimer = 0;
        
        Emotion_Happiness = Emotion_Max;
        
        Array.Clear(Inventory, 0, Inventory.Length);
        Inventory[0] = T_Item.FirstAidKit;
        Inventory[1] = T_Item.FirstAidKit;
        Inventory[2] = T_Item.GPS;

        Seed = (uint)WL.Math.Random.Fast_Int(0, 10000000);
        
        StartLevel(T_Level.Calm);
    }
    
    private bool RenderColliders = false;
    private bool Immortality     = false;
    private bool IgnoreColliders = false;
    public override void KeyPress(Key Key, bool Down){
        bool __Enter = Key is Key.Enter or Key.Space or Key.N5;
        bool __Up    = Key is Key.W or Key.Up or Key.N8;
        bool __Down  = Key is Key.S or Key.Down or Key.N2;
        bool __Right = Key is Key.D or Key.Right or Key.N6;
        bool __Left  = Key is Key.A or Key.Left or Key.N4;
        
        if(Down){
            if(InMainMenu){
                if(__Enter){ UseMainMenuButton(); }

                if(Interface == T_Interface.None){
                    if(__Up){
                        if(MenuSelectedButton > 0){ MenuSelectedButton -= 1; }
                    }

                    if(__Down){
                        if(MenuSelectedButton < 3){ MenuSelectedButton += 1; }
                    }
                }
            }else{
                if(Key == Key.C){ RenderColliders = !RenderColliders; }
                if(Key == Key.I){ Immortality = !Immortality; }
                if(Key == Key.X){ IgnoreColliders = !IgnoreColliders; }
                if(Key == Key.Home){ WorldPosition = Vector2F.Zero; }

                void UpdSeed(){
                    if(KeyPressed(Key.Alt)){
                        if(KeyPressed(Key.Shift)){ Seed -= 1; }else{ Seed += 1; }
                    }else{
                        if(KeyPressed(Key.Shift)){ Seed = 0; }   
                    }
                    if(KeyPressed(Key.Control)){ Seed = (uint)WL.Math.Random.Fast_Int(0, 10000000); }
                }
                
                if(Key == Key.F1){ UpdSeed(); StartLevel(T_Level.Calm); }
                if(Key == Key.F2){ UpdSeed(); StartLevel(T_Level.Industrial); }

                if(Key == Key.Escape || (Interface == T_Interface.Menu && MenuSelectedButton == 0 && __Enter)){
                    if(Interface == T_Interface.None){ Interface = T_Interface.Menu; }else{ Interface = T_Interface.None; MenuSelectedButton = 0; }
                }

                if(!Dead){
                    if(Key == Key.Tab){ Interface = Interface == T_Interface.None ? T_Interface.Inventory : T_Interface.None; }
                    
                    if(__Enter){ UseItem(); }
                    
                    if(Key == Key.E){ Use(); }

                    if(Key == Key.Backspace){
                        T_Item Item = Inventory[SelectedItem];
                        if(Item != T_Item.Empty){
                            SpawnItem(PlayerX - WorldX, PlayerY - WorldY, Item);
                            Inventory[SelectedItem] = T_Item.Empty;
                        }
                    }
                    
                    switch(Key){
                        case Key.D1:
                            SelectedItem = 0;
                            break;
                        case Key.D2:
                            SelectedItem = 1;
                            break;
                        case Key.D3:
                            SelectedItem = 2;
                            break;
                        case Key.D4:
                            SelectedItem = 3;
                            break;
                        case Key.D5:
                            SelectedItem = 4;
                            break;
                        case Key.D6:
                            SelectedItem = 5;
                            break;
                        case Key.D7:
                            SelectedItem = 6;
                            break;
                        case Key.D8:
                            SelectedItem = 7;
                            break;
                        case Key.D9:
                            SelectedItem = 8;
                            break;
                        case Key.D0:
                            SelectedItem = 9;
                            break;
                        case Key.Minus:
                            SelectedItem = 10;
                            break;
                        case Key.Plus:
                            SelectedItem = 11;
                            break;
                    }
                }

                if(Interface == T_Interface.Inventory){
                    byte OldSelectedItem = SelectedItem;
                    
                    if(__Right){
                        if(SelectedItem > 5){
                            if(SelectedItem < 11){ SelectedItem++; }
                        }else{
                            if(SelectedItem < 5){ SelectedItem++; }
                        }
                    }

                    if(__Left){
                        if(SelectedItem > 5){
                            if(SelectedItem > 6){ SelectedItem--; }
                        }else{
                            if(SelectedItem > 0){ SelectedItem--; }
                        }
                    }

                    if(__Down){
                        if(SelectedItem + 6 < MaxSlots){ SelectedItem += 6; }
                    }
                    
                    if(__Up){
                        if(SelectedItem - 6 > -1){ SelectedItem -= 6; }
                    }

                    if(SelectedItem != OldSelectedItem && KeyPressed(Key.Shift)){
                        (Inventory[SelectedItem], Inventory[OldSelectedItem]) = (Inventory[OldSelectedItem], Inventory[SelectedItem]);
                    }
                }else if(Interface == T_Interface.Menu){
                    if(__Up){
                        if(MenuSelectedButton > 0){ MenuSelectedButton -= 1; }
                    }

                    if(__Down){
                        if(MenuSelectedButton < 1){ MenuSelectedButton += 1; }
                    }

                    if(__Enter){
                        if(MenuSelectedButton == 1){
                            GoToMainMenu();
                        }
                    }
                }
            }
        }
    }

    private void UseItem(){
        T_Item Item = Inventory[SelectedItem];

        if(Item != T_Item.Empty){
            bool RemoveItem = false;
            
            switch(Item){
                case T_Item.FirstAidKit:{
                    if(Health == HealthMax){ return; }
                    
                    Heal(50, true);
                    
                    RemoveItem = true;
                    break;
                }
            }

            if(RemoveItem){
                Inventory[SelectedItem] = 0;
            }
        }
    }

    private bool AddToInventory(T_Item Item){
        for(int i = 0; i < Inventory.Length; i++){
            if(Inventory[i] == T_Item.Empty){
                Inventory[i] = Item;
                return true;
            }
        }
        
        return false;
    }
    
    private void Use(){
        if(InsideCollision == CollisionLayer.L4){
            T_Item Item = (T_Item)CollisionInfo1;
            if(Item != T_Item.Empty){
                if(AddToInventory(Item)){ __Entities.Remove(new EntityKey(CollisionInfo2, (uint)CollisionInfo3)); }
            }
        }
    }

    private void UseMainMenuButton(){
        if(Interface == T_Interface.None){
            switch(MenuSelectedButton){
                case 0:
                case 1: StartGame(); break;
                case 2:{
                    Interface = (T_Interface)1;
                    break;
                }
                case 3:{
                    Quit();
                    break;
                }
            }
        }else{
            Interface = T_Interface.None;
        }
    }

    private void RenderColorText(Image.ImageContext C, string Text, int X, int Y, ColorB Color){
        Font.Render(C, Palette_White, Text, X, Y, Color);
    }

    private void RenderOutlineColorText(Image.ImageContext C, string Text, int X, int Y, ColorB Color, ColorB OutlineColor){
        RenderColorText(C, Text, X - 1, Y, OutlineColor);
        RenderColorText(C, Text, X + 1, Y, OutlineColor);
        RenderColorText(C, Text, X, Y - 1, OutlineColor);
        RenderColorText(C, Text, X, Y + 1, OutlineColor);
        RenderColorText(C, Text, X - 1, Y - 1, OutlineColor);
        RenderColorText(C, Text, X + 1, Y + 1, OutlineColor);
        RenderColorText(C, Text, X - 1, Y + 1, OutlineColor);
        RenderColorText(C, Text, X + 1, Y - 1, OutlineColor);
        
        RenderColorText(C, Text, X, Y, Color);
    }

    private void GenerateTestStructure(int X, int Y){
        T_Block [] Blocks   = Enum.GetValues<T_Block >();
        T_Entity[] Entities = Enum.GetValues<T_Entity>();

        int TotalCount = Blocks.Length + Entities.Length;
        int SquareSize = (int)WL.Math.Ceil(WL.Math.Sqrt(TotalCount));
        int Index = 0;
        for(int Y__ = 0; Y__ < SquareSize; Y__++){
            for(int X__ = 0; X__ < SquareSize; X__++){
                int WorldX = X + X__ * 5;
                int WorldY = Y + Y__ * 5;

                if(Index < Blocks.Length){
                    SetBlock(new Block{ ID = Blocks[Index], X = WorldX, Y = WorldY});
                }else if(Index - Blocks.Length < Entities.Length){
                    SetEntity(new Entity{ ID = Entities[Index - Blocks.Length], X = WorldX, Y = WorldY});
                }else{
                    return;
                }

                Index++;
            }   
        }
    }

    public struct Structure{
        public Structure(string Blocks, string Entities = ""){
            this.Blocks = Blocks; this.Entities = Entities;
        }
        
        public string Blocks{
            get => __Blocks;
            set{
                __Blocks = value;
                __CalculateSize();
            }
        }
        private string __Blocks = "";

        public string Entities{
            get => __Entities;
            set{
                __Entities = value;
                __CalculateSize();
            }
        }
        private string __Entities = "";
        
        public uint Width { get; private set; }
        public uint Height{ get; private set; }

        private void __CalculateSize(){
            string[] Lines1 = Blocks  .Replace("\r", "").Split('\n');
            string[] Lines2 = Entities.Replace("\r", "").Split('\n');

            Width  = (uint)WL.Math.MaxI(Lines1.Max(Line => Line.Length), Lines2.Max(Line => Line.Length));
            Height = (uint)WL.Math.MaxI(Blocks.Count(C => C == '\n') + 1, Entities.Count(C => C == '\n') + 1);
        }
    }
    
    private void GenerateLevel(T_Level Level){
        void __GenerateStructure(int X, int Y, Structure S, uint __Seed, bool ToCenter = true){
            int OffsetX = X;
            int OffsetY = Y;
            if(ToCenter){
                OffsetX -= (int)S.Width  / 2;
                OffsetY -= (int)S.Height / 2;
            }
            if(!string.IsNullOrWhiteSpace(S.Blocks)){ AddScene(S.Blocks, OffsetX, OffsetY, __Seed); }
            if(!string.IsNullOrWhiteSpace(S.Entities)){ AddEntityScene(S.Entities, OffsetX, OffsetY, __Seed); }
        }

        int LEFT_BORDER   = -(int)LevelSize.X - 3;
        int RIGHT_BORDER  =  (int)LevelSize.X + 3;
        int TOP_BORDER    = -(int)LevelSize.Y - 3;
        int BOTTOM_BORDER =  (int)LevelSize.Y + 3;
        
