            //__GenerateStructure(0, 0, Lake, Seed + 123233, false);

            void GenerateWater(uint Seed){
                void GenerateRiver(Vector2I StartPosition, Vector2I EndPosition, uint Width = 3, uint SandWidth = 3, uint Seed = 0){
                    SandWidth += Width;

                    void GenerateRiverPoint(int X, int Y, uint Width, uint SandWidth, uint Seed = 0){
                        bool IsWater(int X, int Y) => GetBlock(X, Y).ID == T_Block.Water;
                        
                        for(int WX = -(int)Width / 2; WX <= Width / 2; WX++){
                            for (int WY = -(int)Width / 2; WY <= Width / 2; WY++){
                                int Px = X + WX;
                                int Py = Y + WY;
                                
                                SetBlock(new Block{ ID = T_Block.Water, X = Px, Y = Py });
                            }
                        }

                        uint Seed__ = Seed + (uint)(X + Y) * (Width + SandWidth);
                        SandWidth = (uint)WL.Math.Random.Fast_Int(0, (int)SandWidth, ref Seed__);
                        
                        for(int WX = -(int)SandWidth / 2; WX <= SandWidth / 2; WX++){
                            for(int WY = -(int)SandWidth / 2; WY <= SandWidth / 2; WY++){
                                int Px = X + WX;
                                int Py = Y + WY;

                                if(!IsWater(Px, Py)){
                                    SetBlock(new Block{ ID = T_Block.Ground_Sand, X = Px, Y = Py });
                                }
                            }
                        }
                    }
                    
                    int DX = EndPosition.X - StartPosition.X;
                    int DY = EndPosition.Y - StartPosition.Y;

                    int Steps = WL.Math.MaxI(WL.Math.AbsI(DX), WL.Math.AbsI(DY));
                    if(Steps == 0){ return; }

                    float StepX = (float)DX / Steps;
                    float StepY = (float)DY / Steps;

                    uint Seed__ = Seed + 6612;
                    
                    for(int i = 0; i <= Steps; i++){
                        int X = (int)WL.Math.Round(StartPosition.X + StepX * i);
                        int Y = (int)WL.Math.Round(StartPosition.Y + StepY * i);

                        Seed__ *= 3;
                        
                        GenerateRiverPoint(X, Y, Width, SandWidth, Seed__);
                    }
                }

                Vector2I GetMeanderPoint(Vector2I StartPosition, Vector2I EndPosition, float T, int MeanderCount, float MaxAmplitude, float Compression){
                    Vector2F Direction = new Vector2F(EndPosition.X - StartPosition.X, EndPosition.Y - StartPosition.Y);
                    float L = WL.Math.Sqrt(Direction.X * Direction.X + Direction.Y * Direction.Y);
                    if(L <= 0.001f){ return StartPosition; }

                    Vector2F Norm = new Vector2F(Direction.X / L, Direction.Y / L);
                    Vector2F Perp = new Vector2F(-Norm.Y, Norm.X);

                    float BaseX = StartPosition.X + Direction.X * T;
                    float BaseY = StartPosition.Y + Direction.Y * T;

                    float BaseWave = WL.Math.Sin(T * WL.Math.PI * MeanderCount);

                    float Envelope = WL.Math.Sin(T * WL.Math.PI);
                    Envelope = WL.Math.Pow(Envelope, Compression);

                    float Amplitude = BaseWave * MaxAmplitude * Envelope;

                    return new Vector2I(
                        (int)WL.Math.Round(BaseX + Perp.X * Amplitude),
                        (int)WL.Math.Round(BaseY + Perp.Y * Amplitude)
                    );
                }
                
                void GenerateMeanderRiver(Vector2I StartPosition, Vector2I EndPosition, uint Width = 3, uint SandWidth = 3, int MeanderCount = 6, float MaxAmplitude = 40, int SmoothSteps = 400, float Compression = 3.5f, uint Seed = 0){
                    Vector2I? Previous = null;

                    uint Seed__ = Seed + 222;
                    
                    for(int i = 0; i <= SmoothSteps; i++){
                        float T = (float)i / SmoothSteps;

                        Vector2I Current = GetMeanderPoint(StartPosition, EndPosition, T, MeanderCount, MaxAmplitude, Compression);

                        if(Previous != null){
                            GenerateRiver(Previous.Value, Current, Width, SandWidth, Seed__);
                            Seed__ += 77778;
                        }

                        Previous = Current;
                    }
                }
                
                void GenerateRiverEcosystem(int TributaryCount = 6, int MainRiverLength = 500, uint Seed = 0){
                    uint Seed__ = Seed - 1020;
                    
                    Vector2I MainStart = new Vector2I(
                        WL.Math.Random.Fast_Int(-(int)LevelSize.X / 2, (int)LevelSize.X / 2, ref Seed__),
                        -(int)LevelSize.Y
                    );

                    Seed__ -= 10;
                    
                    Vector2I MainEnd = new Vector2I(
                        MainStart.X + WL.Math.Random.Fast_Int(-100, 100, ref Seed__),
                        MainStart.Y + MainRiverLength
                    );

                    Seed__ -= 10;
                    
                    uint MainWidth = 6;
                    uint MainSand = 10;
                    
                    GenerateMeanderRiver(MainStart, MainEnd, MainWidth, MainSand, 6, 40, 600, 3f, Seed__);

                    for(int i = 0; i < TributaryCount; i++){
                        float T = WL.Math.Random.Fast_0_1(ref Seed__);

                        Vector2I JoinPoint = GetMeanderPoint(MainStart, MainEnd, T, 6, 40, 3f);

                        uint Seed1__ = Seed__ + 414;
                        uint Seed2__ = Seed1__ + 2133;
                        
                        Vector2I TributaryStart = new Vector2I(
                            JoinPoint.X + WL.Math.Random.Fast_Int(-200, 200, ref Seed1__),
                            JoinPoint.Y - WL.Math.Random.Fast_Int(150, 300, ref Seed2__)
                        );

                        int TributaryLength = WL.Math.AbsI(JoinPoint.Y - TributaryStart.Y);

                        uint TributaryWidth = 2 + (uint)TributaryLength / 200;
                        uint TributarySand = TributaryWidth + 2;

                        Seed__ -= 10001 + (Seed1__ * Seed2__);
                        
                        GenerateMeanderRiver(TributaryStart, JoinPoint, TributaryWidth, TributarySand, 3, 20, 400, 2.5f, Seed__);
                    }
                }
                
                GenerateRiverEcosystem(Seed: Seed);
            }
            GenerateWater(Seed);

            void GenerateGrassLand(uint Seed){
                Seed -= 32;
                for(int y = -(int)LevelSize.Y; y < LevelSize.Y; y += 10){
                    Seed += 511;
                    for(int x = -(int)LevelSize.X; x < LevelSize.X; x += 10){
                        Seed *= 51;
                        
                        uint SeedOffset = (uint)((x + y) * (x * y));
                        uint __Seed1 = Seed + SeedOffset * 222223;
                        uint __Seed2 = Seed + SeedOffset * 212224;
                    
                        __GenerateStructure(x + WL.Math.Random.Fast_Int(-5, 5, ref __Seed1), y + WL.Math.Random.Fast_Int(-5, 5, ref __Seed2), GrassLand, Seed + SeedOffset);
                    }
                }   
            }
            GenerateGrassLand(Seed);

            void GenerateGrassBunch(uint Seed){
                Seed += 111125;
                for(int x = 0; x < 50; x++){
                    Seed -= 161616;
                    
                    uint SeedOffset = (uint)x;
                    uint __Seed1 = Seed + SeedOffset * 222223;
                    uint __Seed2 = Seed + SeedOffset * 212224;
                    uint __Seed3 = Seed + SeedOffset * 124125;

                    Structure __GrassBunch = GrassBunches[WL.Math.Random.Fast_Int(0, GrassBunches.Length - 1, ref __Seed3)];
                    
                    __GenerateStructure(WL.Math.Random.Fast_Int(LEFT_BORDER, RIGHT_BORDER, ref __Seed1), WL.Math.Random.Fast_Int(TOP_BORDER, BOTTOM_BORDER, ref __Seed2), __GrassBunch, Seed + SeedOffset);
                }
            }
            GenerateGrassBunch(Seed);
            
            GenerateTestStructure(-50, -50);
        }
        
        switch(Level){
            case T_Level.Calm: GenerateCalm(Seed); break;
        }
    }
}